# Write a rapid-fire script that catches production when up and immediately calls passwordless login
cat > /tmp/ivx-auth-mint.ts << 'SCRIPT'
const PROD = "https://ivx-holdings-platform.onrender.com";
const OWNER_EMAIL = "iperez4242@gmail.com";

async function checkHealth(): Promise<boolean> {
  try {
    const res = await fetch(`${PROD}/health`, { signal: AbortSignal.timeout(15000) });
    return res.status === 200;
  } catch { return false; }
}

async function passwordlessLogin(): Promise<{ ok: boolean; accessToken?: string; httpCode?: number; error?: string }> {
  try {
    const res = await fetch(`${PROD}/api/ivx/owner-passwordless-login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: OWNER_EMAIL, emergency: "ivx_emergency_recovery" }),
      signal: AbortSignal.timeout(55000),
    });
    const text = await res.text();
    if (!res.ok) {
      return { ok: false, httpCode: res.status, error: text.slice(0, 300) };
    }
    try {
      const data = JSON.parse(text);
      if (data.success && data.accessToken) {
        return { ok: true, accessToken: data.accessToken, httpCode: res.status };
      }
      return { ok: false, httpCode: res.status, error: JSON.stringify({ ...data, accessToken: undefined }).slice(0, 300) };
    } catch {
      return { ok: false, httpCode: res.status, error: text.slice(0, 300) };
    }
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "fetch failed" };
  }
}

async function main() {
  console.log("[AUTH] Starting rapid auth mint loop...");
  for (let attempt = 1; attempt <= 20; attempt++) {
    process.stdout.write(`[AUTH] Attempt ${attempt}: warming up... `);
    const healthy = await checkHealth();
    if (!healthy) {
      console.log("502, retrying...");
      await Bun.sleep(3000);
      continue;
    }
    console.log("UP! Calling passwordless login...");
    const result = await passwordlessLogin();
    if (result.ok && result.accessToken) {
      console.log(`[AUTH] SUCCESS! httpCode=${result.httpCode} tokenLen=${result.accessToken.length}`);
      // Write token to temp file (never to stdout)
      await Bun.write("/tmp/ivx-owner-token.txt", result.accessToken);
      console.log("[AUTH] Token written to /tmp/ivx-owner-token.txt");
      return;
    }
    console.log(`[AUTH] FAILED httpCode=${result.httpCode} error=${result.error?.slice(0, 200)}`);
    await Bun.sleep(2000);
  }
  console.log("[AUTH] EXHAUSTED all attempts");
}

main();
