async function main() {
  // Phase 1: Warm up
  console.log("[1] Warming up...");
  let warm = false;
  for (let i = 1; i <= 25; i++) {
    try {
      const res = await fetch(`${URL}/health`, { signal: AbortSignal.timeout(8000) });
      if (res.status === 200) {
        const data = await res.json();
        if (data.status === "healthy") {
