          warm = true;
          break;
        }
      }
    } catch {}
    await Bun.sleep(1500);
  }
  if (!warm) { console.log("[1] FAILED to warm up"); return; }

  // Phase 2: Passwordless login
  console.log("[2] Passwordless login...");
  let token: string | null = null;
  for (let i = 1; i <= 5; i++) {
    try {
      const res = await fetch(`${URL}/api/ivx/owner-passwordless-login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: OWNER_EMAIL, emergency: "ivx_emergency_recovery" }),
        signal: AbortSignal.timeout(55000),
      });
      const text = await res.text();
      if (text.includes("<!DOCTYPE html>")) {
        console.log(`[2.${i}] RENDER_502`);
        await Bun.sleep(2000);
        continue;
      }
      try {
        const data = JSON.parse(text);
        if (data.success === true && data.accessToken) {
          token = data.accessToken;
          console.log(`[2.${i}] SUCCESS tokenLen=${token.length} method=${data.sessionMethod}`);
          break;
        }
        console.log(`[2.${i}] FAIL rootCause=${data.rootCause} msg=${(data.message ?? "").slice(0, 100)}`);
      } catch {
        console.log(`[2.${i}] NON_JSON: ${text.slice(0, 80)}`);
      }
    } catch (e) {
      console.log(`[2.${i}] ERROR: ${e instanceof Error ? e.message : "unknown"}`);
    }
    await Bun.sleep(1500);
  }

  if (!token) {
    console.log("[2] NO TOKEN OBTAINED");

    // Phase 2b: Check senior developer status (might be public)
    console.log("[2b] Checking senior dev autonomous status...");
    try {
      const res = await fetch(`${URL}/api/ivx/senior-developer/autonomous-mode/status`, {
        signal: AbortSignal.timeout(15000),
      });
      const text = await res.text();
      console.log(`[2b] HTTP ${res.status}: ${text.slice(0, 400)}`);
    } catch (e) {
      console.log(`[2b] ERROR: ${e instanceof Error ? e.message : "unknown"}`);
    }
    return;
  }

  // Phase 3: Verify token
  console.log("[3] Verifying token...");
  try {
    const res = await fetch(`${URL}/api/ivx/senior-developer/worker/status`, {
      headers: { Authorization: `Bearer ${token}` },
      signal: AbortSignal.timeout(15000),
    });
    const text = await res.text();
    console.log(`[3] HTTP ${res.status}: ${text.slice(0, 300)}`);
  } catch (e) {
    console.log(`[3] ERROR: ${e instanceof Error ? e.message : "unknown"}`);
  }

  // Phase 4: Check senior dev blockers
  console.log("[4] Checking credential audit...");
  try {
    const res = await fetch(`${URL}/api/ivx/senior-developer/credential-audit`, {
      headers: { Authorization: `Bearer ${token}` },
      signal: AbortSignal.timeout(15000),
    });
    const text = await res.text();
    // Don't print secrets
    try {
      const data = JSON.parse(text);
      const safe: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(data)) {
        if (typeof v === "string" && v.length > 20) safe[k] = `PRESENT_len=${v.length}`;
        else safe[k] = v;
      }
      console.log(`[4] HTTP ${res.status}: ${JSON.stringify(safe).slice(0, 500)}`);
    } catch {
      console.log(`[4] HTTP ${res.status}: ${text.slice(0, 200)}`);
    }
  } catch (e) {
    console.log(`[4] ERROR: ${e instanceof Error ? e.message : "unknown"}`);
  }
}

main();
